import collections
import datetime
import json
from pathlib import Path

path = Path('/home/r/dev/minor/stackd/testdata/aws/secretsmanager/encryption_audit.json')
data = json.loads(path.read_text())
observations = data['observations']
by_label = {o['label']: o for o in observations}
summary = {'source': Path(__file__).read_text(), 'derived_from': 'Retained observations and owned CloudTrail events only; no absent audit event is interpreted as proof a KMS call did not happen.'}
summary['admission'] = [{k: o[k] for k in ['label', 'actor', 'input', 'result']} for o in observations if o['label'].startswith(('no-value-create-', 'no-value-update-')) and '-describe-' not in o['label'] and '-setup-' not in o['label']]
summary['write_controls'] = [{k: o[k] for k in ['label', 'actor', 'result']} for o in observations if o['label'].startswith(('new-version-write-', 'new-version-replay-'))]
summary['transitions'] = {}
for name, setup in data.get('version_sets', {}).items():
    update = by_label.get(name + '-update-key')
    describe = by_label.get(name + '-describe-after')
    reads = {o['label'].removeprefix(name + '-after-'): o['result']['code'] for o in observations if o['label'].startswith(name + '-after-')}
    summary['transitions'][name] = {'update_result': update['result'] if update else None,
        'metadata_key_after': describe['result'].get('output', {}).get('KmsKeyId') if describe else None,
        'version_read_results': reads,
        'fresh_read_results': {o['label'].removeprefix(name + '-fresh-'): o['result']['code'] for o in observations if o['label'].startswith(name + '-fresh-')}}
events = list(data['audit_events'].values())
summary['audit_event_counts'] = dict(sorted(collections.Counter((e['eventSource'] + ':' + e['eventName']) for e in events).items()))
summary['audit_shapes'] = {}
for event in events:
    key = event['eventSource'] + ':' + event['eventName'] + (':' + event['errorCode'] if 'errorCode' in event else ':Success')
    if key not in summary['audit_shapes']:
        summary['audit_shapes'][key] = {k: event.get(k) for k in ['eventID', 'eventCategory', 'managementEvent', 'readOnly', 'eventType', 'requestParameters', 'responseElements', 'additionalEventData', 'errorCode', 'errorMessage'] if k in event}
summary['kms_validation_events'] = [e['eventID'] for e in events if (e.get('requestParameters') or {}).get('encryptionContext', {}).get('SecretVersionId') == 'RequestToValidateKeyAccess']
summary['kms_version_contexts'] = []
seen = set()
for e in events:
    if e['eventSource'] != 'kms.amazonaws.com':
        continue
    p = e.get('requestParameters') or {}
    if 'encryptionContext' not in p:
        continue
    record = {'event_name': e['eventName'], 'key_id': p.get('keyId'), 'encryption_context': p['encryptionContext'],
              'error_code': e.get('errorCode'), 'resource_arns': [r.get('ARN') for r in e.get('resources', [])]}
    identity = json.dumps(record, sort_keys=True)
    if identity not in seen:
        summary['kms_version_contexts'].append({'example_event_id': e['eventID'], **record})
        seen.add(identity)
batch_obs = by_label.get('audit-batch-mixed')
if batch_obs:
    start = batch_obs['request_started_ms'] / 1000 - 2
    end = batch_obs['request_finished_ms'] / 1000 + 2
    actor = data['actors'][batch_obs['actor']]['session_arn']
    summary['batch_window_events'] = [e for e in events if e['eventSource'] == 'secretsmanager.amazonaws.com' and e['eventName'] in ['BatchGetSecretValue', 'GetSecretValue'] and e.get('userIdentity', {}).get('arn') == actor and start <= datetime.datetime.fromisoformat(e['eventTime'].replace('Z', '+00:00')).timestamp() <= end]
    summary['batch_observation_label'] = batch_obs['label']
# Omission is observable per captured event; it does not establish whole-service completeness.
summary['audit_sensitive_field_presence'] = []
for e in events:
    if e['eventSource'] == 'secretsmanager.amazonaws.com' and e['eventName'] in ['CreateSecret', 'UpdateSecret', 'PutSecretValue', 'GetSecretValue', 'BatchGetSecretValue']:
        request = e.get('requestParameters') or {}
        response = e.get('responseElements') or {}
        fields = [k for k in request if k.lower() in ['secretstring', 'secretbinary']]
        response_fields = [k for k in response if k.lower() in ['secretstring', 'secretbinary']]
        if fields or response_fields:
            summary['audit_sensitive_field_presence'].append({'event_id': e['eventID'], 'request_fields': fields, 'response_fields': response_fields})
summary['kms_sensitive_request_fields'] = [{'event_id': e['eventID'], 'field': k} for e in events if e['eventSource'] == 'kms.amazonaws.com' for k in (e.get('requestParameters') or {}) if k.lower() in ['plaintext', 'ciphertextblob']]
summary['kms_crypto_nonnull_responses'] = [e['eventID'] for e in events if e['eventSource'] == 'kms.amazonaws.com' and e['eventName'] in ['GenerateDataKey', 'Decrypt', 'Encrypt'] and e.get('responseElements') is not None]
summary['key_identities'] = {
    'old_customer_managed_key': data['resources']['keys'][0],
    'new_customer_managed_key': data['resources']['keys'][1],
    'default_aws_managed_key': by_label['default-key-identity']['result']['output']['KeyMetadata']['Arn'],
    'default_describe_omits_kms_key_id': 'KmsKeyId' not in by_label['default-describe']['result']['output']}
summary['no_value_validation_event_ids'] = [e['eventID'] for e in events if e['eventSource'] == 'kms.amazonaws.com' and (e.get('requestParameters') or {}).get('encryptionContext', {}).get('SecretARN') == by_label['no-value-create-full']['result']['output']['ARN']]
summary['default_key_crypto_event_ids'] = [e['eventID'] for e in events if e['eventSource'] == 'kms.amazonaws.com' and (e.get('requestParameters') or {}).get('encryptionContext', {}).get('SecretARN') == by_label['default-create-value']['result']['output']['ARN']]
summary['credential_redaction_verified'] = True
def verify_redaction(value):
    if isinstance(value, dict):
        for key, child in value.items():
            if key.lower() in ['accesskeyid', 'secretaccesskey', 'sessiontoken', 'nexttoken']:
                assert isinstance(child, str) and child.startswith('[REDACTED'), key
            if key == 'CloudTrailEvent':
                verify_redaction(json.loads(child))
            else:
                verify_redaction(child)
    elif isinstance(value, list):
        for child in value:
            verify_redaction(child)
verify_redaction({'observations': observations, 'audit_lookups': data['audit_lookups'], 'audit_events': data['audit_events']})
summary['coverage_limits'] = ['Role/secret tag replication was not exercised: no replicas were created by this probe.',
    'LookupEvents is delayed; only delivered owned events are evidence. The bounded lookup window is not proof of complete audit delivery.',
    'No AWS-managed-key policy was modified. Existing authority.json and its pending-deletion CMK were untouched.',
    'The audit capture filters out unrelated events and redacts live credential identifiers and pagination tokens. Synthetic inert secret values in direct API inputs/results are retained.']
data['summary'] = summary
path.write_text(json.dumps(data, indent=2) + '\n')
print(json.dumps({'failure': data.get('probe_failure'), 'audit_event_counts': summary['audit_event_counts'], 'validation_event_count': len(summary['kms_validation_events']), 'sensitive_audit_fields': summary['audit_sensitive_field_presence'], 'kms_sensitive_fields': summary['kms_sensitive_request_fields'], 'redaction_verified': summary['credential_redaction_verified'], 'cleanup': data['cleanup']}, indent=2))
